var videoWrapper=document.querySelectorAll(".video__wrapper"),presentationVideo=document.querySelector(".presentation__video");function workVideo(e){var o=e.querySelector(".play"),r=e.querySelector("video");o.addEventListener("click",function(e){e.preventDefault(),r.play()}),r.addEventListener("play",function(e){o.classList.add("play--hide")}),r.addEventListener("click",function(e){r.paused?r.play():(r.pause(),o.classList.remove("play--hide"))})}videoWrapper.forEach(e=>{workVideo(e)}),workVideo(presentationVideo);